(() => {
  'use strict';
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const content=$('#consoleContent'), title=$('#viewTitle'), eyebrow=$('#viewEyebrow'), subtitle=$('#viewSubtitle');
  const csrf=$('meta[name="csrf-token"]')?.content||'', toastEl=$('#toast'), modal=$('#appModal'), modalContent=$('#modalContent');
  let state={machines:[],apps:[],commands:[],activity:[],software_requests:[],tickets:[],network_policies:[],employees:[],password_otps:[]};
  let view='overview', query='';
  let policyDraft={machine_id:'',policy:'manual',compliance:'audit',network_policy:''};
  const meta={overview:['Workspace','Overview','Company IT at a glance.'],devices:['Inventory','Devices','Live health, hardware, software and power history.'],employees:['People','Employees','Accounts and assigned company PCs.'],software:['Apps','Software','Approved catalog and deployment source.'],requests:['Review','Requests','Employee software requests and compliance warnings.'],policies:['Control','Policies','Software, device and website restrictions.'],support:['Helpdesk','Support','Employee IT tickets and replies.'],activity:['Audit','Activity','Commands and server-side audit history.']};
  const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
  const fmt=v=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})};
  const rel=v=>{if(!v)return'Never';let s=Math.max(0,Math.round((Date.now()-new Date(v).getTime())/1000));if(s<60)return`${s}s ago`;if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;return`${Math.floor(s/86400)}d ago`};
  const uptime=s=>{s=Number(s||0);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return[d?`${d}d`:null,h?`${h}h`:null,`${m}m`].filter(Boolean).join(' ')};
  const status=(text,cls='info')=>`<span class="status ${esc(cls)}"><i></i>${esc(text)}</span>`;
  const pct=(v)=>Math.max(0,Math.min(100,Number(v)||0));
  const meter=(label,v,note='')=>`<div><small>${esc(label)} ${note?`· ${esc(note)}`:''}</small><div class="meter ${pct(v)>90?'bad':pct(v)>75?'warn':''}"><i style="width:${pct(v)}%"></i></div></div>`;
  const empty=(title='Nothing here yet',text='Data will appear after devices start reporting.')=>`<div class="empty"><b>${esc(title)}</b><p>${esc(text)}</p></div>`;
  function toast(m){toastEl.textContent=m;toastEl.classList.add('show');clearTimeout(toastEl.t);toastEl.t=setTimeout(()=>toastEl.classList.remove('show'),2600)}
  function openModal(html,wide=false){modalContent.innerHTML=html;modal.querySelector('.modal-card').classList.toggle('wide',wide);modal.hidden=false;setTimeout(()=>modal.querySelector('input,select,textarea')?.focus(),20)}
  function closeModal(){modal.hidden=true;modalContent.innerHTML=''}
  async function api(url,options={}){const method=(options.method||'GET').toUpperCase();const headers={'Accept':'application/json',...(options.headers||{})};let body=options.body;if(!['GET','HEAD','OPTIONS'].includes(method)){headers['X-CSRFToken']=csrf;if(body && !(body instanceof FormData)){headers['Content-Type']='application/json'}}const r=await fetch(url,{credentials:'same-origin',...options,method,headers,body});const d=await r.json().catch(()=>({}));if(!r.ok){const msg=d.detail||d.error||`Request failed (${r.status})`;throw new Error(d.error_id?`${msg} · Ref ${d.error_id}`:msg)}return d}
  async function refresh(silent=false){if(!silent)content.innerHTML='<div class="loading"><i></i><span>Loading VarunOps…</span></div>';try{state=await api('/api/bootstrap/');$('#requestBadge').textContent=state.software_requests.filter(x=>x.status==='submitted').length+(state.unauthorized_count||0);$('#ticketBadge').textContent=state.tickets.filter(x=>!['resolved','closed'].includes(x.status)).length;$('#syncStamp').textContent=`Synced ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;render()}catch(e){content.innerHTML=empty('Could not load VarunOps',e.message);toast(e.message)}}
  const visibleMachines=()=>state.machines.filter(m=>!query||`${m.name} ${m.branch||''} ${m.serial_number||''} ${m.ip_address||''} ${m.system_info?.model||''}`.toLowerCase().includes(query));
  const appInstalled=(m,slug)=>(m.installed_apps||[]).find(x=>x.slug===slug);
  const unauthorized=()=>state.machines.flatMap(m=>(m.unauthorized_software||[]).filter(x=>!x.resolved).map(x=>({...x,machine:m})));
  const sourceLabel=a=>a.source_type==='github'?'GitHub Release':a.source_type==='direct'?'Direct HTTPS':'Winget';
  function render(){const m=meta[view]||meta.overview;eyebrow.textContent=m[0];title.textContent=m[1];subtitle.textContent=m[2];$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const f={overview:renderOverview,devices:renderDevices,employees:renderEmployees,software:renderSoftware,requests:renderRequests,policies:renderPolicies,support:renderSupport,activity:renderActivity}[view];content.innerHTML=f();bind();location.hash=view==='overview'?'':view}

  function renderOverview(){const online=state.machines.filter(m=>m.online).length,openTickets=state.tickets.filter(t=>!['resolved','closed'].includes(t.status)).length,pending=state.software_requests.filter(r=>r.status==='submitted').length,warnings=unauthorized();return`
    <div class="stats"><article class="stat"><span>Managed PCs</span><strong>${state.machines.length}</strong><small>${online} online now</small></article><article class="stat"><span>Software warnings</span><strong>${warnings.length}</strong><small>Unapproved detections</small></article><article class="stat"><span>Pending requests</span><strong>${pending}</strong><small>Waiting for IT</small></article><article class="stat"><span>Open tickets</span><strong>${openTickets}</strong><small>Employee support</small></article></div>
    <div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Device health</h2><p>Latest agent report, refreshed automatically.</p></div><button class="secondary-btn small-btn" data-jump="devices">View all</button></div>${deviceRows(state.machines.slice(0,7))}</section>
    <section class="panel"><div class="panel-head"><div><h2>Needs attention</h2><p>Software and request alerts.</p></div><button class="secondary-btn small-btn" data-jump="requests">Review</button></div><div class="warning-list">${warnings.slice(0,5).map(w=>warningMarkup(w)).join('')||empty('All clear','No unapproved software is active.')}</div></section></div>
    <section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest audited server actions.</p></div></div>${activityMarkup(state.activity.slice(0,8))}</section>`}

  function deviceRows(rows){if(!rows.length)return empty('No devices','Pair an employee PC to start reporting.');return`<div class="device-list">${rows.map(m=>{const x=m.latest_metric||{};return`<article class="device-row"><div><b>${esc(m.name)}</b><small>${esc(m.branch||'No branch')} · ${esc(m.system_info?.model||m.device_type||'Windows PC')}</small></div><div>${status(m.online?'Online':'Offline',m.online?'online':'offline')}<small>${esc(rel(m.last_seen))}</small></div><div class="hide-md">${meter('RAM',x.memory_percent||0,`${Number(x.memory_used_gb||0).toFixed(1)}/${Number(x.memory_total_gb||0).toFixed(1)} GB`)}</div><div class="hide-md">${meter('Storage',x.storage_percent||0,`${Number(x.storage_used_gb||0).toFixed(0)}/${Number(x.storage_total_gb||0).toFixed(0)} GB`)}</div><div class="hide-md"><small>CPU</small><b>${Number(x.cpu_percent||0).toFixed(0)}%</b></div><button class="secondary-btn small-btn" data-device="${esc(m.id)}">Details</button></article>`}).join('')}</div>`}

  function renderDevices(){return`<section class="panel"><div class="panel-head"><div><h2>Managed devices</h2><p>Click Details for hardware, software, policy and power history.</p></div><div class="toolbar"><a class="secondary-btn small-btn" href="/api/devices/export-assets.csv">Export asset CSV</a><span class="notice">Live values ~60 sec · software inventory ~15 min.</span></div></div>${deviceRows(visibleMachines())}</section>`}

  function renderEmployees(){
    const rows=state.employees.filter(e=>!query||`${e.full_name} ${e.username} ${e.employee_code||''} ${e.department||''} ${e.branch||''} ${e.email||''}`.toLowerCase().includes(query));
    const otps=state.password_otps||[];
    const otpPanel=otps.length?`<section class="panel"><div class="panel-head"><div><h2>Pending verification OTPs</h2><p>Employee requested these codes. Give the code only to the correct employee after identity confirmation.</p></div>${status(`${otps.length} pending`,'warning')}</div><div class="detail-grid">${otps.map(o=>`<div class="detail-box"><h3>${esc(o.employee_name)}</h3><div class="kv"><span>Username</span><b>${esc(o.username)}</b><span>Employee code</span><b>${esc(o.employee_code||'—')}</b><span>PC</span><b>${esc(o.machine_name||'—')}</b><span>Expires</span><b>${esc(fmt(o.expires_at))}</b></div><div class="detail-stat" style="margin-top:12px"><span>6-digit OTP</span><b style="font-size:28px;letter-spacing:.18em">${esc(o.otp)}</b></div><button class="secondary-btn small-btn" data-copy-otp="${esc(o.otp)}" style="margin-top:10px">Copy OTP</button></div>`).join('')}</div></section>`:'';
    return`${otpPanel}<section class="panel"><div class="panel-head"><div><h2>Employees</h2><p>Temporary login → PC pairing → first full sync → Admin OTP → permanent password.</p></div><button class="primary-btn" data-add-employee>Add employee</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Department</th><th>Branch</th><th>PC</th><th>Onboarding</th><th>Password</th><th></th></tr></thead><tbody>${rows.map(e=>{const m=state.machines.find(x=>x.id===e.assigned_machine_id);return`<tr><td><span class="cell-main"><b>${esc(e.full_name||e.username)}</b><small>${esc(e.username)} · ${esc(e.email||'No email')} · ${esc(e.employee_code||'No code')}</small></span></td><td>${esc(e.department||'—')}</td><td>${esc(e.branch||'—')}</td><td>${e.assigned_machine_name?`<span class="cell-main"><b>${esc(e.assigned_machine_name)}</b><small>${m?esc(rel(m.last_seen)):'paired'}</small></span>`:status('Waiting for PC','warning')}</td><td>${status((e.onboarding_state||'pair_device').replaceAll('_',' '),e.onboarding_state==='active'?'success':'warning')}</td><td><span class="cell-main"><b>${esc(e.password_status||'—')}</b><small>${e.password_changed_at?'Changed '+esc(fmt(e.password_changed_at)):e.temporary_password_issued_at?'Temp issued '+esc(fmt(e.temporary_password_issued_at)):'—'}</small></span></td><td><div class="toolbar"><button class="secondary-btn small-btn" data-edit-employee="${esc(e.username)}">Edit</button><button class="ghost-btn small-btn" data-reissue-temp="${esc(e.username)}">New temp</button></div></td></tr>`}).join('')||`<tr><td colspan="7">${empty('No employees','Create the first employee account.')}</td></tr>`}</tbody></table></div></section>`}

  function renderSoftware(){const rows=state.apps.filter(a=>!query||`${a.name} ${a.publisher||''} ${a.category||''} ${a.winget_id||''} ${a.github_repo||''}`.toLowerCase().includes(query));return`
    <section class="panel"><div class="panel-head"><div><h2>Software catalog</h2><p>Winget, verified HTTPS installers, or public GitHub Release assets.</p></div><button class="primary-btn" data-add-app>Add software</button></div><div class="notice"><b>GitHub workflow:</b> publish your redistributable/internal EXE or MSI as a Release asset, enter <code>owner/repo</code> + exact asset filename, and VarunOps resolves the latest published release. SHA-256 verification is still required.</div></section>
    <section class="panel"><div class="panel-head"><div><h2>Approved apps</h2><p>Use PC policy to decide Required / Optional / Blocked per device.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>App</th><th>Source</th><th>Version</th><th>Employee store</th><th>Deployment</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="cell-main"><b>${esc(a.name)}</b><small>${esc(a.publisher||'Publisher not set')} · ${esc(a.category||'General')}</small></div></td><td>${status(sourceLabel(a),a.source_type==='winget'?'info':'warning')}</td><td>${esc(a.latest_version||'—')}</td><td>${a.employee_visible?status('Visible','success'):status('IT only')}</td><td><span class="cell-main"><b>${esc(a.source_type==='winget'?(a.winget_id||'Missing ID'):(a.installer_kind||'EXE').toUpperCase())}</b><small>${a.source_type==='github'?esc(`${a.github_repo||'Missing repo'} · ${a.github_asset_name||'Missing asset'}`):a.source_type==='direct'?esc(a.installer_url||'Missing HTTPS URL'):'Microsoft Winget source'}</small></span></td><td><div class="toolbar">${a.source_type==='github'?`<button class="secondary-btn small-btn" data-github-refresh="${esc(a.slug)}">Refresh GitHub</button>`:''}<button class="secondary-btn small-btn" data-edit-app="${esc(a.slug)}">Edit</button><button class="ghost-btn small-btn" data-app-policy="${esc(a.slug)}">PC policy</button></div></td></tr>`).join('')||`<tr><td colspan="6">${empty('No software','Add your first company-approved app.')}</td></tr>`}</tbody></table></div></section>
    <section class="panel"><div class="panel-head"><div><h2>Deploy to one PC</h2><p>Commands remain queued until that device is switched from TEST to LIVE.</p></div></div><form id="deployForm" class="form"><div class="form-grid"><label>Device<select name="machine_id" required><option value="">Choose device</option>${state.machines.map(m=>`<option value="${esc(m.id)}">${esc(m.name)} · ${esc(m.branch||'')}</option>`).join('')}</select></label><label>Software<select name="app_slug" required><option value="">Choose software</option>${state.apps.map(a=>`<option value="${esc(a.slug)}">${esc(a.name)}</option>`).join('')}</select></label><label>Action<select name="action"><option value="install">Install</option><option value="update">Update</option><option value="uninstall">Uninstall</option></select></label><label>&nbsp;<button class="primary-btn" type="submit">Queue action</button></label></div></form></section>`}

  function renderRequests(){const reqs=state.software_requests.filter(r=>!query||`${r.employee_name} ${r.machine_name} ${r.app_name} ${r.status}`.toLowerCase().includes(query));const warns=unauthorized();const submitted=reqs.filter(r=>r.status==='submitted');return`<section class="panel"><div class="panel-head"><div><h2>Unapproved software</h2><p>Select multiple detections and resolve them in one action.</p></div><div class="toolbar"><button class="ghost-btn small-btn" data-select-all-warnings>Select all</button><button class="secondary-btn small-btn" data-bulk-warning="allow">Allow selected</button><button class="danger-btn small-btn" data-bulk-warning="uninstall">Uninstall selected</button></div></div><div class="warning-list">${warns.map(warningMarkup).join('')||empty('No active warnings','All reported software is approved, baseline, or explicitly allowed.')}</div></section><section class="panel"><div class="panel-head"><div><h2>Employee software requests</h2><p>Approve or reject many submitted requests together.</p></div><div class="toolbar"><button class="ghost-btn small-btn" data-select-all-requests>Select submitted</button><button class="primary-btn small-btn" data-bulk-request="approve">Approve selected</button><button class="danger-btn small-btn" data-bulk-request="reject">Reject selected</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th></th><th>Employee</th><th>PC</th><th>Software</th><th>Action</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${reqs.map(r=>`<tr><td>${r.status==='submitted'?`<input type="checkbox" data-request-select value="${esc(r.id)}">`:''}</td><td>${esc(r.employee_name)}</td><td>${esc(r.machine_name)}</td><td><span class="cell-main"><b>${esc(r.app_name)}</b><small>Latest ${esc(r.latest_version||'—')}</small></span></td><td>${esc(r.action)}</td><td>${esc(r.reason||'—')}</td><td>${status(r.status,r.status)}</td><td>${r.status==='submitted'?`<div class="toolbar"><button class="primary-btn small-btn" data-request="approve" data-request-id="${esc(r.id)}">Approve</button><button class="danger-btn small-btn" data-request="reject" data-request-id="${esc(r.id)}">Reject</button></div>`:''}</td></tr>`).join('')||`<tr><td colspan="8">${empty('No requests','Employee software requests will appear here.')}</td></tr>`}</tbody></table></div></section>`}

  function renderPolicies(){const d=policyDraft;return`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Device policy</h2><p>Select a PC. Your selections stay saved on screen during background refresh.</p></div></div><form id="devicePolicyForm" class="form"><label>Device<select name="machine_id" required><option value="">Choose device</option>${state.machines.map(m=>`<option value="${esc(m.id)}" ${String(d.machine_id)===String(m.id)?'selected':''}>${esc(m.name)} · ${esc(m.branch||'')}</option>`).join('')}</select></label><div class="form-grid"><label>Software command mode<select name="policy"><option value="manual" ${d.policy==='manual'?'selected':''}>Manual</option><option value="automatic" ${d.policy==='automatic'?'selected':''}>Automatic updates</option><option value="locked" ${d.policy==='locked'?'selected':''}>Locked</option></select></label><label>Compliance<select name="compliance"><option value="audit" ${d.compliance==='audit'?'selected':''}>Audit only</option><option value="enforce" ${d.compliance==='enforce'?'selected':''}>Enforce required/blocked catalog apps</option></select></label></div><label>Website policy<select name="network_policy"><option value="" ${!d.network_policy?'selected':''}>No browsing restriction</option>${state.network_policies.map(p=>`<option value="${p.id}" ${String(d.network_policy)===String(p.id)?'selected':''}>${esc(p.name)} · ${esc(p.mode)}${p.strict_browsing?' · Strict':''}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Apply to selected PC</button></form></section><section class="panel"><div class="panel-head"><div><h2>Website policies</h2><p>URL allow/block rules plus optional Strict Browsing Lock.</p></div><button class="secondary-btn small-btn" data-add-network>Add policy</button></div>${state.network_policies.length?state.network_policies.map(p=>{const assigned=state.machines.filter(m=>String(m.network_policy)===String(p.id));const applied=assigned.filter(m=>String(m.system_info?.network_policy_applied_id||'')===String(p.id)&&Number(m.system_info?.network_policy_applied_revision||0)===Number(p.revision)&&m.system_info?.network_policy_verified===true).length;return `<div class="warning-item"><div><b>${esc(p.name)}</b><small>${esc(p.mode)} · ${p.machine_count||0} PC(s) · rev ${p.revision} · <b>${applied}/${assigned.length} endpoint applied</b></small></div><div class="toolbar"><span class="chip ${assigned.length&&applied===assigned.length?'green':''}">${assigned.length&&applied===assigned.length?'Applied ✓':'Pending endpoint sync'}</span><span class="chip">Edge ${p.enforce_edge?'✓':'—'} · Chrome ${p.enforce_chrome?'✓':'—'}${p.strict_browsing?' · Strict ✓':''}</span><button class="secondary-btn small-btn" data-network-all="${p.id}">Apply to all managed PCs</button></div></div>`}).join(''):empty('No website policies','Add a policy, then assign it to a PC.')}</section></div><section class="panel"><div class="notice warn"><b>All managed PCs:</b> applying a website policy here updates every registered/enabled PC. Online PCs receive it on the next agent sync; offline PCs receive it when they reconnect.<br><br><b>Strict Browsing Lock:</b> when enabled, VarunOps blocks common unmanaged browsers (Firefox/Brave/Opera/Vivaldi/etc.) from outbound network access, while Edge/Chrome stay controlled by the URL rules. This is a free endpoint lockdown, not a full Secure Web Gateway.</div></section>`}
  function renderSupport(){const rows=state.tickets.filter(t=>!query||`${t.employee_name} ${t.subject} ${t.status} ${t.category}`.toLowerCase().includes(query));return`<section class="panel"><div class="panel-head"><div><h2>IT support tickets</h2><p>Open a ticket to read and reply.</p></div></div><div class="ticket-list">${rows.map(t=>`<button class="ticket-row" data-ticket="${esc(t.id)}"><span><b>${esc(t.subject)}</b><small>${esc(t.employee_name)} · ${esc(t.machine_name||'No PC')} · ${esc(t.category)} · ${esc(fmt(t.updated_at||t.created_at))}</small></span>${status(t.status,t.status)}</button>`).join('')||empty('No tickets','Employee support tickets will appear here.')}</div></section>`}
  function renderActivity(){return`<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Command queue</h2><p>Endpoint work and results.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>PC</th><th>App</th><th>Action</th><th>Status</th><th>Requested</th></tr></thead><tbody>${state.commands.slice(0,80).map(c=>`<tr><td>${esc(c.machine_name)}</td><td>${esc(c.app_name)}</td><td>${esc(c.action)}</td><td>${status(c.status,c.status)}</td><td>${esc(fmt(c.requested_at))}</td></tr>`).join('')||`<tr><td colspan="5">${empty('No commands')}</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Audit log</h2><p>Server recorded actions.</p></div></div>${activityMarkup(state.activity.slice(0,60))}</section></div>`}
  function activityMarkup(rows){return`<div class="activity">${rows.map(a=>`<div class="activity-row"><i class="activity-dot ${esc(a.kind)}"></i><span><b>${esc(a.message)}</b><small>${esc(a.event)}${a.machine_name?' · '+esc(a.machine_name):''}${a.actor?' · '+esc(a.actor):''}</small></span><time>${esc(rel(a.created_at))}</time></div>`).join('')||empty('No activity')}</div>`}

  function warningMarkup(w){return`<div class="warning-item warning-select-row"><label class="select-check"><input type="checkbox" data-warning-select value="${esc(w.id)}"></label><div><b>${esc(w.display_name||'Unknown software')}</b><small>${esc(w.machine?.name||'PC')} · ${esc(w.version||'')} · ${esc(w.publisher||'Unknown publisher')}</small></div><div class="toolbar"><button class="secondary-btn small-btn" data-warning="allow" data-warning-id="${esc(w.id)}">Allow</button><button class="danger-btn small-btn" data-warning="uninstall" data-warning-id="${esc(w.id)}">Uninstall</button></div></div>`}

  function showDevice(id){const m=state.machines.find(x=>x.id===id);if(!m)return;openDeviceTab(m,'overview',0)}
  function openDeviceTab(m,tab='overview',page=0){const x=m.latest_metric||{},info=m.system_info||{},events=m.recent_power_events||[],software=m.detected_software||[],alerts=(m.unauthorized_software||[]).filter(x=>!x.resolved),a=m.asset_details||{},mon=(info.monitors||[])[0]||{},mouse=(info.mouse_devices||[])[0]||{},kbd=(info.keyboard_devices||[])[0]||{};const tabs=[['overview','Overview'],['hardware','Hardware'],['software','Software'],['network','Network & policy'],['power','Power'],['compliance','Compliance']];const nav=`<div class="detail-tabs">${tabs.map(([k,l])=>`<button class="${tab===k?'active':''}" data-device-tab="${k}">${l}</button>`).join('')}</div>`;let body='';if(tab==='overview'){const rows=[['Employee',m.assigned_employee_name||'—'],['Hostname',m.name],['Status',m.online?'Online':'Offline'],['Branch',m.branch||'—'],['Serial',m.serial_number||'—'],['IP',m.ip_address||'—'],['Windows',`${info.os_caption||m.os_version||'—'} ${info.os_build||''}`.trim()],['Processor',info.cpu_name||info.processor||'—'],['RAM',`${Number(x.memory_used_gb||0).toFixed(1)} / ${Number(x.memory_total_gb||info.memory_total_gb||0).toFixed(1)} GB`],['Storage',`${Number(x.storage_used_gb||0).toFixed(0)} / ${Number(x.storage_total_gb||0).toFixed(0)} GB`],['Uptime',uptime(x.uptime_seconds)],['Last sync',rel(m.last_seen)]];body=`<div class="detail-stats"><div class="detail-stat"><span>CPU</span><b>${Number(x.cpu_percent||0).toFixed(0)}%</b>${meter('',x.cpu_percent||0)}</div><div class="detail-stat"><span>RAM</span><b>${Number(x.memory_percent||0).toFixed(0)}%</b><small>${Number(x.memory_used_gb||0).toFixed(1)} / ${Number(x.memory_total_gb||0).toFixed(1)} GB</small></div><div class="detail-stat"><span>Storage</span><b>${Number(x.storage_percent||0).toFixed(0)}%</b><small>${Number(x.storage_used_gb||0).toFixed(0)} / ${Number(x.storage_total_gb||0).toFixed(0)} GB</small></div></div><section class="detail-box"><h3>Top device details</h3><div class="linear-details">${rows.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v||'—')}</b></div>`).join('')}</div></section>`}else if(tab==='hardware'){body=`<div class="detail-grid"><section class="detail-box"><h3>CPU & motherboard</h3><div class="kv"><span>Manufacturer</span><b>${esc(info.manufacturer||'—')}</b><span>Model</span><b>${esc(info.model||'—')}</b><span>Processor</span><b>${esc(info.cpu_name||info.processor||'—')}</b><span>Processor ID</span><b>${esc(info.cpu_id||'—')}</b><span>Cores / threads</span><b>${esc(info.cpu_cores||'—')} / ${esc(info.cpu_logical_processors||'—')}</b><span>Motherboard</span><b>${esc([info.motherboard_manufacturer,info.motherboard_model].filter(Boolean).join(' ')||'—')}</b><span>Board serial</span><b>${esc(info.motherboard_serial||'—')}</b><span>BIOS</span><b>${esc(info.bios_version||'—')} · ${esc(info.bios_serial||m.serial_number||'—')}</b></div></section><section class="detail-box"><h3>Memory, disks & display</h3><div class="kv"><span>RAM modules</span><b>${esc((info.memory_modules||[]).map(r=>`${r.capacity_gb||'?'}GB ${r.manufacturer||''} ${r.serial||''}`.trim()).join(' · ')||'—')}</b><span>Disks</span><b>${esc((info.physical_disks||[]).map(d=>`${d.model||'Disk'} ${d.size_gb||''}GB ${d.serial||''}`.trim()).join(' | ')||'—')}</b><span>GPU</span><b>${esc((info.gpu||[]).join(', ')||'—')}</b><span>Monitor</span><b>${esc([mon.manufacturer,mon.model].filter(Boolean).join(' ')||'—')}</b><span>Monitor serial</span><b>${esc(mon.serial||'—')}</b><span>Resolution</span><b>${esc(info.resolution||'—')}</b><span>Mouse</span><b>${esc([mouse.manufacturer,mouse.name].filter(Boolean).join(' ')||'—')}</b><span>Keyboard</span><b>${esc(kbd.name||kbd.description||'—')}</b></div><button class="secondary-btn small-btn" style="margin-top:10px" data-edit-assets="${esc(m.id)}">Edit manual asset fields</button></section></div>`}else if(tab==='software'){const per=10,total=Math.max(1,Math.ceil(software.length/per)),pg=Math.max(0,Math.min(page,total-1)),slice=software.slice(pg*per,pg*per+per);body=`<section class="detail-box"><div class="panel-head"><div><h3>Software inventory · ${software.length}</h3><small>10 items per page</small></div><span class="chip">Page ${pg+1}/${total}</span></div><div class="software-page">${slice.map(s=>`<div><span><b>${esc(s.display_name)}</b><small>${esc(s.version||'—')} · ${esc(s.publisher||'Unknown publisher')}</small></span><span class="chip ${s.classification==='unauthorized'?'':'green'}">${esc(s.classification)}</span></div>`).join('')||'<small>No inventory yet.</small>'}</div><div class="pager"><button class="secondary-btn small-btn" data-device-page="${pg-1}" ${pg<=0?'disabled':''}>Previous</button><button class="secondary-btn small-btn" data-device-page="${pg+1}" ${pg>=total-1?'disabled':''}>Next</button></div></section>`}else if(tab==='network'){body=`<div class="detail-grid"><section class="detail-box"><h3>Network</h3><div class="kv"><span>IP</span><b>${esc(m.ip_address||'—')}</b><span>Signed-in user</span><b>${esc(info.windows_user||'—')}</b><span>Domain</span><b>${esc(info.domain||'—')}</b><span>Adapters</span><b>${esc((info.network_adapters||[]).map(n=>n.name||n.description||n.mac).filter(Boolean).join(' · ')||'—')}</b></div></section><section class="detail-box"><h3>Policy</h3><div class="kv"><span>Command mode</span><b>${esc(m.policy)}</b><span>Compliance</span><b>${esc(m.compliance_mode)}</b><span>Website policy</span><b>${esc(m.network_policy_name||'None')}</b><span>Endpoint policy</span><b>${m.network_policy?(String(info.network_policy_applied_id||'')===String(m.network_policy)&&info.network_policy_verified===true?'Applied ✓':'Pending / agent update needed'):'None'}</b><span>Agent version</span><b>${esc(info.agent_version||'—')}</b><span>Execution</span><b>${m.agent_live_mode?'LIVE':'TEST'}</b><span>Last seen</span><b>${esc(rel(m.last_seen))}</b></div><div class="app-actions" style="margin-top:10px"><button class="secondary-btn small-btn" data-jump-close="policies">Change policy</button><button class="${m.agent_live_mode?'danger-btn':'primary-btn'} small-btn" data-agent-mode="${m.agent_live_mode?'0':'1'}" data-agent-machine="${esc(m.id)}">${m.agent_live_mode?'Switch to TEST':'Enable LIVE actions'}</button></div></section></div>`}else if(tab==='power'){body=`<section class="detail-box"><h3>Power history</h3><div class="activity">${events.map(e=>`<div class="activity-row"><i class="activity-dot ${e.event_type==='unexpected_shutdown'?'error':e.event_type==='shutdown'?'warning':'success'}"></i><span><b>${esc(e.event_type.replaceAll('_',' '))}</b></span><time>${esc(fmt(e.occurred_at))}</time></div>`).join('')||'<small>No power history yet.</small>'}</div></section>`}else{body=`<section class="detail-box"><h3>Unapproved software · ${alerts.length}</h3><div class="warning-list">${alerts.map(warningMarkup).join('')||'<small>No active compliance warnings.</small>'}</div></section>`}openModal(`<div class="detail-head"><div class="title"><h2>${esc(m.name)}</h2><small>${esc(m.branch||'No branch')} · ${esc(m.serial_number||'No serial')} · ${esc(m.ip_address||'No IP')}</small></div>${status(m.online?'Online':'Offline',m.online?'online':'offline')}</div>${nav}<div class="device-tab-body">${body}</div>`,true);bindDeviceModal(m);$$('[data-device-tab]',modal).forEach(b=>b.addEventListener('click',()=>openDeviceTab(m,b.dataset.deviceTab,0)));$$('[data-device-page]',modal).forEach(b=>b.addEventListener('click',()=>openDeviceTab(m,'software',Number(b.dataset.devicePage))))}

  function bindDeviceModal(m){
    $('[data-edit-assets]',modal)?.addEventListener('click',()=>editAssets(m));
    $$('[data-jump-close]',modal).forEach(b=>b.addEventListener('click',()=>{closeModal();view=b.dataset.jumpClose;render()}));
    $$('[data-agent-mode]',modal).forEach(b=>b.addEventListener('click',async()=>{
      const live=b.dataset.agentMode==='1';
      if(live&&!confirm('Enable LIVE software actions for this PC? Install/update/uninstall commands will be allowed to execute.'))return;
      try{await api('/api/agent-mode/',{method:'POST',body:JSON.stringify({machine_id:b.dataset.agentMachine,live})});closeModal();toast(live?'LIVE actions enabled':'Switched to TEST mode');await refresh(true)}catch(e){toast(e.message)}
    }));
  }

  function editAssets(m){
    const a=m.asset_details||{};
    openModal(`<h2>${esc(m.name)} · Asset details</h2><p>Fill only physical labels/accessories that Windows cannot reliably detect.</p><form id="adminAssetForm" class="form"><input type="hidden" name="machine_id" value="${esc(m.id)}"><div class="form-grid"><label>Asset tag<input name="asset_tag" value="${esc(a.asset_tag||'')}"></label><label>PIN / Inventory no.<input name="pin_number" value="${esc(a.pin_number||'')}"></label><label>Vendor<input name="vendor" value="${esc(a.vendor||'')}"></label><label>Purchase date<input type="date" name="purchase_date" value="${esc(a.purchase_date||'')}"></label><label>Desk / location<input name="desk_location" value="${esc(a.desk_location||'')}"></label><label>Monitor brand<input name="monitor_brand" value="${esc(a.monitor_brand||'')}"></label><label>Monitor model<input name="monitor_model" value="${esc(a.monitor_model||'')}"></label><label>Monitor serial<input name="monitor_serial" value="${esc(a.monitor_serial||'')}"></label><label>Screen size<input name="screen_size" value="${esc(a.screen_size||'')}"></label><label>Mouse brand<input name="mouse_brand" value="${esc(a.mouse_brand||'')}"></label><label>Mouse model<input name="mouse_model" value="${esc(a.mouse_model||'')}"></label><label>Mouse serial<input name="mouse_serial" value="${esc(a.mouse_serial||'')}"></label><label>Keyboard brand<input name="keyboard_brand" value="${esc(a.keyboard_brand||'')}"></label><label>Keyboard model<input name="keyboard_model" value="${esc(a.keyboard_model||'')}"></label><label>Keyboard serial<input name="keyboard_serial" value="${esc(a.keyboard_serial||'')}"></label><label>UPS brand<input name="ups_brand" value="${esc(a.ups_brand||'')}"></label><label>UPS model<input name="ups_model" value="${esc(a.ups_model||'')}"></label><label>UPS serial<input name="ups_serial" value="${esc(a.ups_serial||'')}"></label></div><label>Notes<textarea name="notes" rows="3">${esc(a.notes||'')}</textarea></label><button class="primary-btn" type="submit">Save asset details</button></form>`);
    $('#adminAssetForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/devices/asset-details/',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});closeModal();toast('Asset details saved');await refresh(true)}catch(err){toast(err.message)}});
  }

  function appForm(app=null){
    const a=app||{}, source=a.source_type||'winget';
    openModal(`<h2>${app?'Edit':'Add'} software</h2><p>Choose a trusted deployment source. Winget is simplest; GitHub Release is suitable for your own redistributable/internal EXE or MSI.</p><form id="appForm" class="form">
      <div class="form-grid"><label>Name<input name="name" value="${esc(a.name||'')}" required></label><label>Slug<input name="slug" value="${esc(a.slug||'')}" ${app?'readonly':''} required placeholder="company-tool"></label><label>Publisher<input name="publisher" value="${esc(a.publisher||'')}"></label><label>Category<input name="category" value="${esc(a.category||'General')}"></label><label>Latest version<input name="latest_version" value="${esc(a.latest_version||'')}"></label><label>Homepage<input name="homepage_url" value="${esc(a.homepage_url||'')}" placeholder="https://..."></label></div>
      <label>Description<textarea name="description" rows="3">${esc(a.description||'')}</textarea></label>
      <label>Detection names <span class="hint">Comma-separated Windows DisplayName values</span><input name="detection_names" value="${esc((a.detection_names||[]).join(', '))}" placeholder="Company Tool, Company Tool x64"></label>
      <label>Installer source<select name="source_type" id="sourceType"><option value="winget" ${source==='winget'?'selected':''}>Winget</option><option value="github" ${source==='github'?'selected':''}>GitHub Release</option><option value="direct" ${source==='direct'?'selected':''}>Direct HTTPS EXE/MSI</option></select></label>
      <div id="wingetFields" class="source-box"><label>Winget package ID<input name="winget_id" value="${esc(a.winget_id||'')}" placeholder="Google.Chrome"><span class="hint">Required for Winget. Optional for GitHub/Direct, but useful for reliable uninstall if the package also exists in Winget.</span></label></div>
      <div id="githubFields" class="source-box"><div class="form-grid"><label>GitHub repository<input name="github_repo" value="${esc(a.github_repo||'')}" placeholder="VarunMachhi/company-software"></label><label>Release asset filename<input name="github_asset_name" value="${esc(a.github_asset_name||'')}" placeholder="CompanyTool-Setup.exe"></label><label>Installer type<select name="installer_kind"><option value="exe" ${a.installer_kind!=='msi'?'selected':''}>EXE</option><option value="msi" ${a.installer_kind==='msi'?'selected':''}>MSI</option></select></label><label>SHA-256 fallback<input name="installer_sha256" value="${esc(a.installer_sha256||'')}" maxlength="64" placeholder="Only needed if GitHub asset has no digest"></label></div><div class="notice">VarunOps resolves the latest published public GitHub Release and exact asset filename. If GitHub publishes a SHA-256 digest, it is used automatically.</div></div>
      <div id="directFields" class="source-box"><div class="form-grid"><label>Installer URL<input name="installer_url" value="${esc(a.installer_url||'')}" placeholder="https://vendor.example/app.exe"></label><label>Installer type<select name="installer_kind_direct"><option value="exe" ${a.installer_kind!=='msi'?'selected':''}>EXE</option><option value="msi" ${a.installer_kind==='msi'?'selected':''}>MSI</option></select></label></div><label>SHA-256<input name="installer_sha256_direct" value="${esc(a.installer_sha256||'')}" maxlength="64" placeholder="64 hex characters"></label></div>
      <div id="commonInstallerFields"><div class="form-grid"><label>Install arguments <span class="hint">One argument per line</span><textarea name="install_args" rows="3">${esc((a.install_args||[]).join('\n'))}</textarea></label><label>Update arguments <span class="hint">One argument per line</span><textarea name="update_args" rows="3">${esc((a.update_args||[]).join('\n'))}</textarea></label></div></div>
      <div class="form-grid"><label class="inline-check"><input type="checkbox" name="employee_visible" ${a.employee_visible!==false?'checked':''}> Show in employee store</label><label class="inline-check"><input type="checkbox" name="license_required" ${a.license_required?'checked':''}> License required</label></div>
      <label>License notes<input name="license_notes" value="${esc(a.license_notes||'')}" placeholder="Example: license assigned by IT"></label><label>Update notes<input name="update_notes" value="${esc(a.update_notes||'')}"></label><label>Icon URL (optional)<input name="icon_url" value="${esc(a.icon_url||'')}" placeholder="https://..."></label>
      <button class="primary-btn" type="submit">${app?'Save changes':'Add software'}</button></form>` ,true);
    const toggle=()=>{const s=$('#sourceType').value;$('#wingetFields').style.display='block';$('#githubFields').style.display=s==='github'?'block':'none';$('#directFields').style.display=s==='direct'?'block':'none'};
    $('#sourceType').addEventListener('change',toggle);toggle();$('#appForm').addEventListener('submit',saveApp);
  }

  async function saveApp(e){
    e.preventDefault();
    const f=new FormData(e.currentTarget),o=Object.fromEntries(f.entries()),source=String(f.get('source_type')||'winget');
    o.employee_visible=f.has('employee_visible');o.license_required=f.has('license_required');o.enabled=true;
    o.detection_names=String(o.detection_names||'').split(',').map(x=>x.trim()).filter(Boolean);
    o.install_args=String(o.install_args||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
    o.update_args=String(o.update_args||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
    if(source==='direct'){o.installer_kind=String(f.get('installer_kind_direct')||'exe');o.installer_sha256=String(f.get('installer_sha256_direct')||'').trim();}
    if(source==='github'){o.installer_kind=String(f.get('installer_kind')||'exe');}
    try{await api('/api/catalog/save/',{method:'POST',body:JSON.stringify(o)});closeModal();toast('Software saved');await refresh(true)}catch(err){toast(err.message)}
  }

  function appPolicy(slug){const a=state.apps.find(x=>x.slug===slug);openModal(`<h2>${esc(a.name)} · PC policy</h2><p>Required = must be present. Optional = employee may request it. Blocked = remove/deny the catalog app in Enforce mode.</p><form id="appPolicyForm" class="form"><label>Device<select name="machine_id" required><option value="">Choose device</option>${state.machines.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><label>Policy<select name="mode"><option value="required">Required</option><option value="optional">Optional</option><option value="blocked">Blocked</option></select></label><label class="inline-check"><input type="checkbox" name="auto_update" checked> Automatically keep current</label><button class="primary-btn" type="submit">Apply</button></form>`);$('#appPolicyForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/app-policies/assign/',{method:'POST',body:JSON.stringify({machine_ids:[f.get('machine_id')],app_slug:slug,mode:f.get('mode'),auto_update:f.has('auto_update')})});closeModal();toast('App policy applied');await refresh(true)}catch(err){toast(err.message)}})}

  function editEmployee(username){const e=state.employees.find(x=>x.username===username);if(!e)return;const first=e.first_name||'',last=e.last_name||'';openModal(`<h2>Edit employee</h2><p>Email is optional contact information. Password verification codes are delivered through the IT Admin panel.</p><form id="editEmployeeForm" class="form"><div class="form-grid"><label>Username<input value="${esc(e.username)}" disabled></label><label>Employee code<input name="employee_code" value="${esc(e.employee_code||'')}"></label><label>First name<input name="first_name" value="${esc(first)}" required></label><label>Last name<input name="last_name" value="${esc(last)}"></label><label>Email (optional)<input type="email" name="email" value="${esc(e.email||'')}"></label><label>Department<input name="department" value="${esc(e.department||'')}"></label><label>Branch<input name="branch" value="${esc(e.branch||'')}"></label><label>Job title<input name="job_title" value="${esc(e.job_title||'')}"></label><label>Phone<input name="phone" value="${esc(e.phone||'')}"></label></div><button class="primary-btn" type="submit">Save employee</button></form>`);$('#editEmployeeForm').addEventListener('submit',async ev=>{ev.preventDefault();try{const data=Object.fromEntries(new FormData(ev.currentTarget).entries());await api(`/api/employees/${encodeURIComponent(username)}/update/`,{method:'POST',body:JSON.stringify(data)});closeModal();toast('Employee updated');await refresh(true)}catch(err){toast(err.message)}})}

  function addEmployee(){openModal(`<h2>Add employee</h2><p>Creates a temporary login. Employee connects the PC, requests an OTP, then IT gives the 6-digit code before the employee sets a permanent password.</p><form id="employeeForm" class="form"><div class="form-grid"><label>Username<input name="username" required placeholder="varun"></label><label>Employee code<input name="employee_code" placeholder="EMP-001"></label><label>First name<input name="first_name" required></label><label>Last name<input name="last_name"></label><label>Email (optional)<input type="email" name="email"></label><label>Department<input name="department"></label><label>Branch<input name="branch"></label><label>Job title<input name="job_title"></label></div><button class="primary-btn" type="submit">Create employee</button></form>`);$('#employeeForm').addEventListener('submit',async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget).entries());try{const r=await api('/api/employees/create/',{method:'POST',body:JSON.stringify(o)});openModal(`<h2>Employee created</h2><p>Copy this temporary password now. Permanent passwords are never visible to IT.</p><div class="notice"><b>Username:</b> ${esc(r.profile.username)}<br><b>Email:</b> ${esc(r.profile.email||'Not set')}<br><b>Temporary password:</b> <code>${esc(r.temporary_password)}</code></div><button class="primary-btn" data-close-modal style="margin-top:12px">Done</button>`);$('[data-close-modal]').addEventListener('click',closeModal);await refresh(true)}catch(err){toast(err.message)}})}

  async function reissueTemp(username){if(!confirm(`Generate a new temporary password for ${username}?`))return;try{const r=await api(`/api/employees/${encodeURIComponent(username)}/reissue-temp/`,{method:'POST',body:'{}'});openModal(`<h2>Temporary password regenerated</h2><p>Copy it now. It cannot be retrieved later.</p><div class="notice"><b>Username:</b> ${esc(r.username)}<br><b>Temporary password:</b> <code>${esc(r.temporary_password)}</code></div>`);await refresh(true)}catch(e){toast(e.message)}}

  function addNetwork(){openModal(`<h2>Add website policy</h2><p>Allowlist mode blocks all non-approved URLs in managed Edge/Chrome. Strict Browsing Lock also blocks common unmanaged browsers from web access.</p><form id="networkForm" class="form"><label>Name<input name="name" required placeholder="Clinic work only"></label><label>Mode<select name="mode"><option value="allowlist">Allow only selected sites</option><option value="blocklist">Block selected sites</option></select></label><label>Allowed sites<textarea name="allowed_sites" rows="5" placeholder="dncc.in\nmail.google.com"></textarea><span class="hint">One host/pattern per line. For YouTube use simply youtube.com (it also matches subdomains). VarunOps normalizes [*.]youtube.com and https://youtube.com/* automatically.</span></label><label>Blocked sites<textarea name="blocked_sites" rows="4" placeholder="example.com"></textarea></label><div class="form-grid"><label class="inline-check"><input type="checkbox" name="enforce_edge" checked> Microsoft Edge</label><label class="inline-check"><input type="checkbox" name="enforce_chrome" checked> Google Chrome</label></div><label class="inline-check"><input type="checkbox" name="strict_browsing" checked> Strict Browsing Lock — block common unmanaged browsers from outbound web access</label><div class="notice warn">Recommended for standard employee PCs. Test on one PC first. This does not block every possible custom/VPN/tunnel application.</div><button class="primary-btn" type="submit">Save policy</button></form>`);$('#networkForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),o=Object.fromEntries(f.entries());o.allowed_sites=String(o.allowed_sites||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);o.blocked_sites=String(o.blocked_sites||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);o.enforce_edge=f.has('enforce_edge');o.enforce_chrome=f.has('enforce_chrome');o.strict_browsing=f.has('strict_browsing');o.enabled=true;try{await api('/api/network-policies/save/',{method:'POST',body:JSON.stringify(o)});closeModal();toast('Website policy saved');await refresh(true)}catch(err){toast(err.message)}})}

  function openTicket(id){const t=state.tickets.find(x=>x.id===id);if(!t)return;openModal(`<div class="detail-head"><div class="title"><h2>${esc(t.subject)}</h2><small>${esc(t.employee_name)} · ${esc(t.machine_name||'No assigned PC')} · ${esc(t.category)}</small></div>${status(t.status,t.status)}</div><p>${esc(t.description)}</p><div class="activity" style="margin:14px 0">${(t.messages||[]).map(m=>`<div class="activity-row"><i class="activity-dot ${m.author_is_staff?'success':'info'}"></i><span><b>${esc(m.author_name)}</b><small>${esc(m.body||'')}${m.attachment?` · attachment: ${esc(m.attachment.original_name)}`:''}</small></span><time>${esc(fmt(m.created_at))}</time></div>`).join('')||empty('No replies')}</div><form id="ticketReplyForm" class="form"><label>Reply<textarea name="body" rows="3" required></textarea></label><button class="primary-btn" type="submit">Send reply</button></form><div class="toolbar" style="margin-top:12px"><button class="secondary-btn small-btn" data-ticket-action="assign">Assign to me</button><button class="secondary-btn small-btn" data-ticket-action="in_progress">In progress</button><button class="primary-btn small-btn" data-ticket-action="resolved">Resolve</button><button class="ghost-btn small-btn" data-ticket-action="closed">Close</button></div>`);$('#ticketReplyForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/tickets/${encodeURIComponent(id)}/messages/`,{method:'POST',body:JSON.stringify({body:new FormData(e.currentTarget).get('body')})});toast('Reply sent');closeModal();await refresh(true);openTicket(id)}catch(err){toast(err.message)}});$$('[data-ticket-action]',modal).forEach(b=>b.addEventListener('click',async()=>{try{await api(`/api/tickets/${encodeURIComponent(id)}/action/`,{method:'POST',body:JSON.stringify({action:b.dataset.ticketAction})});toast('Ticket updated');closeModal();await refresh(true)}catch(err){toast(err.message)}}))}

  async function review(id,decision){try{await api(`/api/software-requests/${encodeURIComponent(id)}/action/`,{method:'POST',body:JSON.stringify({decision})});toast(decision==='approve'?'Request approved':'Request rejected');await refresh(true)}catch(e){toast(e.message)}}
  async function warning(id,action){try{await api(`/api/compliance/unauthorized/${encodeURIComponent(id)}/action/`,{method:'POST',body:JSON.stringify({action})});toast(action==='allow'?'Software allowed on this PC':'Removal queued');await refresh(true)}catch(e){toast(e.message)}}
  async function bulkWarnings(action){const ids=$$('[data-warning-select]:checked').map(x=>x.value);if(!ids.length)return toast('Select at least one warning');if(action==='uninstall'&&!confirm(`Queue uninstall for ${ids.length} selected item(s)?`))return;try{const r=await api('/api/compliance/unauthorized/bulk-action/',{method:'POST',body:JSON.stringify({event_ids:ids,action})});toast(`${r.updated} warning(s) updated`);await refresh(true)}catch(e){toast(e.message)}}
  async function bulkRequests(decision){const ids=$$('[data-request-select]:checked').map(x=>x.value);if(!ids.length)return toast('Select at least one submitted request');try{const r=await api('/api/software-requests/bulk-action/',{method:'POST',body:JSON.stringify({request_ids:ids,decision})});toast(r.skipped?.length?`${r.updated} updated · ${r.skipped.length} skipped`:`${r.updated} request(s) updated`);await refresh(true)}catch(e){toast(e.message)}}
  async function refreshGithub(slug){try{const r=await api('/api/catalog/github-refresh/',{method:'POST',body:JSON.stringify({slug})});toast(`GitHub synced: ${r.latest_version||r.github_release_tag||'latest'}`);await refresh(true)}catch(e){toast(e.message)}}
  async function deploy(form){const f=new FormData(form);try{const r=await api('/api/commands/',{method:'POST',body:JSON.stringify({action:f.get('action'),targets:[{machine_id:f.get('machine_id'),app_slug:f.get('app_slug')}]})});toast(r.created?`${r.created} command queued`:(r.blocked?.[0]||'No command created'));await refresh(true)}catch(e){toast(e.message)}}
  async function applyDevicePolicy(form){const f=new FormData(form),id=f.get('machine_id');if(!id)return toast('Choose a device first');policyDraft={machine_id:id,policy:String(f.get('policy')||'manual'),compliance:String(f.get('compliance')||'audit'),network_policy:String(f.get('network_policy')||'')};try{await api('/api/policies/assign/',{method:'POST',body:JSON.stringify({machine_ids:[id],policy:policyDraft.policy})});await api('/api/compliance/mode/',{method:'POST',body:JSON.stringify({machine_ids:[id],mode:policyDraft.compliance})});await api('/api/network-policies/assign/',{method:'POST',body:JSON.stringify({machine_ids:[id],policy_id:policyDraft.network_policy||null})});toast('Device policy applied');await refresh(true)}catch(e){toast(e.message)}}
  async function applyNetworkAll(policyId){const ids=state.machines.filter(m=>m.enabled!==false).map(m=>m.id);if(!ids.length)return toast('No managed PCs found');const p=state.network_policies.find(x=>String(x.id)===String(policyId));if(!confirm(`Apply ${p?.name||'this website policy'} to all ${ids.length} managed PC(s)? Offline PCs will receive it when they reconnect.`))return;try{const r=await api('/api/network-policies/assign/',{method:'POST',body:JSON.stringify({machine_ids:ids,policy_id:policyId})});toast(`${p?.name||'Website policy'} applied to ${r.updated} PC(s)`);await refresh(true)}catch(e){toast(e.message)}}
  function bindPolicyDraft(){const form=$('#devicePolicyForm');if(!form)return;const device=form.elements.machine_id;device?.addEventListener('change',()=>{const id=device.value;const m=state.machines.find(x=>String(x.id)===String(id));policyDraft.machine_id=id;if(m){policyDraft.policy=m.policy||'manual';policyDraft.compliance=m.compliance_mode||'audit';policyDraft.network_policy=m.network_policy?String(m.network_policy):'';form.elements.policy.value=policyDraft.policy;form.elements.compliance.value=policyDraft.compliance;form.elements.network_policy.value=policyDraft.network_policy}else{policyDraft={machine_id:'',policy:'manual',compliance:'audit',network_policy:''}}});['policy','compliance','network_policy'].forEach(name=>form.elements[name]?.addEventListener('change',e=>{policyDraft[name]=String(e.target.value||'')}));}

  function bind(){$$('[data-copy-otp]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copyOtp);toast('OTP copied')}catch{toast('OTP: '+b.dataset.copyOtp)}}));$$('[data-jump]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.jump;render()}));$$('[data-device]').forEach(b=>b.addEventListener('click',()=>showDevice(b.dataset.device)));$$('[data-edit-employee]').forEach(b=>b.addEventListener('click',()=>editEmployee(b.dataset.editEmployee)));$$('[data-reissue-temp]').forEach(b=>b.addEventListener('click',()=>reissueTemp(b.dataset.reissueTemp)));$$('[data-edit-app]').forEach(b=>b.addEventListener('click',()=>appForm(state.apps.find(x=>x.slug===b.dataset.editApp))));$('[data-add-app]')?.addEventListener('click',()=>appForm());$$('[data-app-policy]').forEach(b=>b.addEventListener('click',()=>appPolicy(b.dataset.appPolicy)));$('[data-add-employee]')?.addEventListener('click',addEmployee);$('[data-add-network]')?.addEventListener('click',addNetwork);$$('[data-request]').forEach(b=>b.addEventListener('click',()=>review(b.dataset.requestId,b.dataset.request)));$$('[data-warning]').forEach(b=>b.addEventListener('click',()=>warning(b.dataset.warningId,b.dataset.warning)));$$('[data-ticket]').forEach(b=>b.addEventListener('click',()=>openTicket(b.dataset.ticket)));$$('[data-github-refresh]').forEach(b=>b.addEventListener('click',()=>refreshGithub(b.dataset.githubRefresh)));$('[data-select-all-warnings]')?.addEventListener('click',()=>$$('[data-warning-select]').forEach(x=>x.checked=true));$('[data-select-all-requests]')?.addEventListener('click',()=>$$('[data-request-select]').forEach(x=>x.checked=true));$$('[data-bulk-warning]').forEach(b=>b.addEventListener('click',()=>bulkWarnings(b.dataset.bulkWarning)));$$('[data-bulk-request]').forEach(b=>b.addEventListener('click',()=>bulkRequests(b.dataset.bulkRequest)));$$('[data-network-all]').forEach(b=>b.addEventListener('click',()=>applyNetworkAll(b.dataset.networkAll)));$('#deployForm')?.addEventListener('submit',e=>{e.preventDefault();deploy(e.currentTarget)});$('#devicePolicyForm')?.addEventListener('submit',e=>{e.preventDefault();applyDevicePolicy(e.currentTarget)});bindPolicyDraft();$$('[data-jump-close]').forEach(b=>b.addEventListener('click',()=>{closeModal();view=b.dataset.jumpClose;render()}));$$('[data-agent-mode]').forEach(b=>b.addEventListener('click',async()=>{const live=b.dataset.agentMode==='1';if(live&&!confirm('Enable LIVE software actions for this PC? Install/update/uninstall commands will be allowed to execute.'))return;try{await api('/api/agent-mode/',{method:'POST',body:JSON.stringify({machine_id:b.dataset.agentMachine,live})});closeModal();toast(live?'LIVE actions enabled':'Switched to TEST mode');await refresh(true)}catch(e){toast(e.message)}}))}
  $$('.nav-item').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render()}));$('#globalSearch').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});$('#refreshData').addEventListener('click',()=>refresh(true));$('#modalClose').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)closeModal()});
  const h=location.hash.replace('#','');if(meta[h])view=h;refresh();setInterval(()=>refresh(true),10000);
})();
